// ═══ SYNCHRONIZED: lock auto-released on exception ═══
synchronized (account) {
    account.debit(amount);  // throws InsufficientFundsException!
}
// Lock is RELEASED even though exception was thrown!
// Other threads CAN now acquire the lock.
// JVM bytecode:
//   monitorenter        ← acquire lock
//   ... debit() code ...
//   monitorexit         ← normal exit: release lock
//   goto end
//   [exception handler]
//   monitorexit         ← exceptional exit: release lock!
//   athrow              ← rethrow the exception

// ═══ ReentrantLock: must release in finally! ═══
ReentrantLock lock = new ReentrantLock();
lock.lock();
try {
    account.debit(amount);  // might throw!
} finally {
    lock.unlock();  // MUST be in finally! Otherwise lock held forever!
}

// ❌ WRONG — lock never released on exception!
lock.lock();
account.debit(amount);  // exception → lock.unlock() never called!
lock.unlock();           // never reached!
// DEADLOCK: all other threads waiting for this lock FOREVER!

// ═══ BYTECODE PROOF (javap -c) ═══
// public void syncMethod();
//   Code:
//     0: aload_1
//     1: monitorenter         ← acquire lock
//     2: ... body ...
//     8: monitorexit          ← normal exit
//     9: goto 17
//    12: astore_2             ← exception handler
//    13: aload_1
//    14: monitorexit          ← exceptional exit (auto-generated!)
//    15: aload_2
//    16: athrow               ← rethrow exception
//    17: return
