// ─── File: src/test/java/com/bank/syncex/ExceptionInSyncTest.java ───
package com.bank.syncex;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import static org.assertj.core.api.Assertions.*;

class ExceptionInSyncTest {

    // ═══ SYNCHRONIZED: lock released on exception ═══
    @Test
    void synchronized_lockReleasedOnException() throws InterruptedException {
        Object lock = new Object();
        boolean[] secondThreadGotLock = {false};

        // Thread-1: acquires lock, throws exception
        Thread t1 = new Thread(() -> {
            synchronized (lock) {
                throw new RuntimeException("Settlement failed!");
                // Lock RELEASED by JVM even though exception thrown!
            }
        });
        t1.start();
        t1.join();  // wait for t1 to finish (with exception)

        // Thread-2: can acquire the lock? YES!
        Thread t2 = new Thread(() -> {
            synchronized (lock) {
                secondThreadGotLock[0] = true;  // got it!
            }
        });
        t2.start();
        t2.join();

        assertThat(secondThreadGotLock[0]).isTrue();  // lock was released!
    }

    // ═══ ReentrantLock WITHOUT finally: lock STUCK on exception ═══
    @Test
    void reentrantLock_withoutFinally_lockStuck() {
        ReentrantLock lock = new ReentrantLock();

        try {
            lock.lock();
            throw new RuntimeException("Settlement failed!");
            // lock.unlock() is AFTER the throw — never reached!
        } catch (RuntimeException e) {
            // Exception caught, but lock is STILL held!
            assertThat(lock.isLocked()).isTrue();  // STUCK!
            assertThat(lock.isHeldByCurrentThread()).isTrue();
        }

        // Manually unlock to cleanup this test
        lock.unlock();
    }

    // ═══ ReentrantLock WITH finally: correct ═══
    @Test
    void reentrantLock_withFinally_lockReleased() {
        ReentrantLock lock = new ReentrantLock();

        try {
            lock.lock();
            throw new RuntimeException("Settlement failed!");
        } catch (RuntimeException e) {
            // exception handled
        } finally {
            lock.unlock();  // ALWAYS release! Even on exception!
        }

        assertThat(lock.isLocked()).isFalse();  // released!
    }

    // ═══ Real scenario: other threads not blocked after exception ═══
    @Test
    void otherThreads_notBlockedAfterException() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch done = new CountDownLatch(1);

        // Thread throws exception inside synchronized
        Thread failing = new Thread(() -> {
            try {
                synchronized (lock) {
                    throw new RuntimeException("DB connection failed!");
                }
            } catch (RuntimeException e) { /* handled */ }
        });
        failing.start();
        failing.join();

        // Subsequent thread can acquire the lock
        Thread next = new Thread(() -> {
            synchronized (lock) {
                done.countDown();  // got the lock!
            }
        });
        next.start();

        boolean completed = done.await(1, TimeUnit.SECONDS);
        assertThat(completed).isTrue();  // next thread got the lock!
    }
}
